{"term":"pansexual","lang":"pt-BR","script":"latin","romanization":null,"category":"identities_orientations","subcategory":null,"concept":"pansexual","is_novel_concept":false,"register":"loanword","crude":3,"technical":65,"recognition_pct_current":75,"recognition_pct_peak":75,"peak_year":null,"regional":null,"definition":"A person attracted to others regardless of sex or gender identity; loanword from English widely used in Brazilian LGBTQ+ communities and media.","english_term":"pansexual","english_translation_quality":"direct","notes":"Retains English form unchanged; recognized primarily by younger, urban, and LGBTQ+-adjacent populations."}
{"term":"lésbica","lang":"pt-BR","script":"latin","romanization":null,"category":"identities_orientations","subcategory":null,"concept":"lesbian","is_novel_concept":false,"register":"clinical","crude":10,"technical":55,"recognition_pct_current":98,"recognition_pct_peak":98,"peak_year":null,"regional":null,"definition":"A woman sexually and/or romantically attracted to other women; the standard clinical and identity term in Brazilian Portuguese.","english_term":"lesbian","english_translation_quality":"direct","notes":"Universally understood across generations and regions; carries mild clinical register but is used freely in everyday speech."}
{"term":"gay","lang":"pt-BR","script":"latin","romanization":null,"category":"identities_orientations","subcategory":null,"concept":"gay","is_novel_concept":false,"register":"loanword","crude":10,"technical":30,"recognition_pct_current":99,"recognition_pct_peak":99,"peak_year":null,"regional":null,"definition":"Fully assimilated English loanword for a gay man or non-heterosexual identity more broadly; the most common neutral term across all demographics in Brazil.","english_term":"gay","english_translation_quality":"direct","notes":"Pronounced /gɛj/ or /gaj/ depending on region; universally understood by all ages; has largely displaced older clinical terms like 'homossexual' in everyday use."}
{"term":"transgênero","lang":"pt-BR","script":"latin","romanization":null,"category":"identities_orientations","subcategory":null,"concept":"transgender","is_novel_concept":false,"register":"clinical","crude":2,"technical":78,"recognition_pct_current":83,"recognition_pct_peak":83,"peak_year":null,"regional":null,"definition":"A person whose gender identity differs from the sex assigned at birth; the standard clinical and activist term in Brazilian Portuguese.","english_term":"transgender","english_translation_quality":"direct","notes":"Growing recognition in line with media coverage; coexists with the more culturally embedded 'travesti' as a distinct identity category in Brazilian discourse."}
{"term":"travesti","lang":"pt-BR","script":"latin","romanization":null,"category":"identities_orientations","subcategory":null,"concept":"travesti_identity","is_novel_concept":true,"register":"slang_neutral","crude":22,"technical":30,"recognition_pct_current":98,"recognition_pct_peak":98,"peak_year":null,"regional":null,"definition":"A specifically Brazilian and Latin American gender identity for people assigned male at birth who adopt feminine gender expression (often including hormones and breast implants) but who may explicitly reject the Western 'transgender woman' label as a distinct cultural and political identity.","english_term":null,"english_translation_quality":"none","notes":"Critically distinct from English 'transvestite' (a cross-dresser, not a gender identity) and not simply synonymous with 'transgender woman' — many travestis reject the latter label. Has a strong historical association with street sex work but is also a proud political identity in Brazilian activism and law. Recognized as a distinct gender category in Brazilian legal and health policy contexts."}
{"term":"intersexo","lang":"pt-BR","script":"latin","romanization":null,"category":"identities_orientations","subcategory":null,"concept":"intersex","is_novel_concept":false,"register":"clinical","crude":2,"technical":83,"recognition_pct_current":58,"recognition_pct_peak":58,"peak_year":null,"regional":null,"definition":"A person born with sex characteristics that do not fit typical binary definitions of male or female; the standard clinical and activist term in Brazilian Portuguese.","english_term":"intersex","english_translation_quality":"direct","notes":"Relatively low recognition outside medical and activist contexts; older populations may be unfamiliar with the term entirely."}
{"term":"queer","lang":"pt-BR","script":"latin","romanization":null,"category":"identities_orientations","subcategory":null,"concept":"queer_identity","is_novel_concept":false,"register":"loanword","crude":18,"technical":22,"recognition_pct_current":68,"recognition_pct_peak":68,"peak_year":null,"regional":null,"definition":"English loanword used as an umbrella identity term for non-heterosexual and/or non-cisgender Brazilians; known primarily among younger, urban, and educated LGBTQ+-adjacent populations.","english_term":"queer","english_translation_quality":"direct","notes":"Retains English pronunciation; carries academic and activist register; significantly less integrated than 'gay'; older Brazilians may not recognize it as an identity term at all."}
{"term":"cisgênero","lang":"pt-BR","script":"latin","romanization":null,"category":"identities_orientations","subcategory":null,"concept":"cisgender","is_novel_concept":false,"register":"clinical","crude":2,"technical":78,"recognition_pct_current":65,"recognition_pct_peak":65,"peak_year":null,"regional":null,"definition":"A person whose gender identity aligns with the sex assigned at birth; standard clinical and activist descriptor in Brazilian Portuguese.","english_term":"cisgender","english_translation_quality":"direct","notes":"Often abbreviated 'cis'; recognition is strongly correlated with LGBTQ+ exposure, education level, and urban residence; unfamiliar to much of the general population."}
{"term":"não-binário","lang":"pt-BR","script":"latin","romanization":null,"category":"identities_orientations","subcategory":null,"concept":"non_binary","is_novel_concept":false,"register":"subculture","crude":2,"technical":65,"recognition_pct_current":70,"recognition_pct_peak":70,"peak_year":null,"regional":null,"definition":"A person whose gender identity does not fall exclusively within the traditional binary categories of man or woman; direct calque translation of English 'non-binary'.","english_term":"non-binary","english_translation_quality":"direct","notes":"Also written 'não binário' without hyphen; recognition growing rapidly among younger generations; in Brazilian Portuguese, speakers using this identity sometimes adopt gender-neutral language endings (e.g., '-e' suffix)."}
{"term":"demissexual","lang":"pt-BR","script":"latin","romanization":null,"category":"identities_orientations","subcategory":null,"concept":"demisexual","is_novel_concept":false,"register":"subculture","crude":2,"technical":58,"recognition_pct_current":38,"recognition_pct_peak":38,"peak_year":null,"regional":null,"definition":"A person who experiences sexual attraction only after forming a significant emotional bond with someone; loanword from English 'demisexual'.","english_term":"demisexual","english_translation_quality":"direct","notes":"Known almost exclusively within LGBTQ+/asexuality-spectrum online communities; extremely low recognition among the general Brazilian public."}
{"term":"polissexual","lang":"pt-BR","script":"latin","romanization":null,"category":"identities_orientations","subcategory":null,"concept":"pansexual","is_novel_concept":false,"register":"subculture","crude":3,"technical":58,"recognition_pct_current":22,"recognition_pct_peak":22,"peak_year":null,"regional":null,"definition":"A person attracted to multiple but not necessarily all genders; distinct from pansexual in that specific genders may fall outside the person's attraction.","english_term":"polysexual","english_translation_quality":"approximate","notes":"Mapped to 'pansexual' as nearest registry entry; polysexual and pansexual are meaningfully distinct (polysexual = multiple genders, not all; pansexual = all genders regardless). Extremely low recognition even within activist spaces; the pansexual/polysexual distinction is rarely observed in casual Brazilian usage."}
{"term":"andrógino","lang":"pt-BR","script":"latin","romanization":null,"category":"identities_orientations","subcategory":null,"concept":"non_binary","is_novel_concept":false,"register":"clinical","crude":5,"technical":58,"recognition_pct_current":80,"recognition_pct_peak":80,"peak_year":null,"regional":null,"definition":"A person combining or embodying both masculine and feminine characteristics in appearance or gender identity; can denote aesthetic presentation or a gender identity distinct from the binary.","english_term":"androgynous / androgyne","english_translation_quality":"approximate","notes":"Mapped to non_binary as closest registry entry; in Brazilian Portuguese usage 'andrógino' frequently describes aesthetic androgyny (a visual quality, not necessarily a gender identity) — context determines whether it is a descriptor or an identity claim."}
{"term":"fluido","lang":"pt-BR","script":"latin","romanization":null,"category":"identities_orientations","subcategory":null,"concept":"gender_fluid","is_novel_concept":false,"register":"subculture","crude":2,"technical":58,"recognition_pct_current":58,"recognition_pct_peak":58,"peak_year":null,"regional":null,"definition":"Shorthand for 'gênero fluido'; a person whose gender identity shifts or varies over time rather than remaining fixed.","english_term":"gender fluid","english_translation_quality":"direct","notes":"Used both as the standalone identity marker 'fluido/a' and in the full phrase 'gênero fluido'; recognition growing with younger generations and LGBTQ+ media coverage."}
{"term":"viado","lang":"pt-BR","script":"latin","romanization":null,"category":"identities_orientations","subcategory":null,"concept":"gay_man_slur","is_novel_concept":false,"register":"slang_crude","crude":88,"technical":0,"recognition_pct_current":99,"recognition_pct_peak":99,"peak_year":null,"regional":null,"definition":"The most common Brazilian Portuguese slur for a gay man, especially an effeminate one; phonetically reduced spoken variant of 'veado'.","english_term":"faggot","english_translation_quality":"approximate","notes":"More common in informal speech than the full form 'veado'; one of the most frequently used anti-gay slurs in Brazil; partially reclaimed within gay communities, especially in northeastern Brazil and in carnival and drag culture. Severity is strongly context-dependent."}
{"term":"veado","lang":"pt-BR","script":"latin","romanization":null,"category":"identities_orientations","subcategory":null,"concept":"gay_man_slur","is_novel_concept":false,"register":"slang_crude","crude":88,"technical":0,"recognition_pct_current":99,"recognition_pct_peak":99,"peak_year":null,"regional":null,"definition":"Primary written-form slur for a gay man in Brazilian Portuguese; literally means 'deer' (male cervid), with the homosexual meaning derived from the passive/submissive position the animal is imagined to occupy.","english_term":"faggot","english_translation_quality":"approximate","notes":"The deer etymology is the standard explanation though debated; 'viado' is the more common phonetic reduction in speech. Both forms are among the most loaded anti-gay slurs in the Brazilian lexicon; widely reclaimed in queer communities."}
{"term":"bicha","lang":"pt-BR","script":"latin","romanization":null,"category":"identities_orientations","subcategory":null,"concept":"effeminate_gay_man","is_novel_concept":false,"register":"slang_crude","crude":74,"technical":0,"recognition_pct_current":99,"recognition_pct_peak":99,"peak_year":null,"regional":null,"definition":"A deeply embedded Brazilian slur for a gay man, especially an effeminate one; also means 'worm', 'bug', or 'creature' in other registers; extensively reclaimed within gay and queer culture.","english_term":"faggot / queen","english_translation_quality":"approximate","notes":"One of the most culturally complex LGBTQ+ words in Brazilian Portuguese: simultaneously a violent slur and a fully reclaimed community identity marker (e.g., 'bicha má', 'bichice', carnival self-identification). Reclamation is widespread but incomplete — remains offensive from out-group mouths. Also standard in northeastern Brazil as an almost affectionate peer term among gay men."}
{"term":"bichona","lang":"pt-BR","script":"latin","romanization":null,"category":"identities_orientations","subcategory":null,"concept":"effeminate_gay_man","is_novel_concept":false,"register":"slang_crude","crude":80,"technical":0,"recognition_pct_current":95,"recognition_pct_peak":95,"peak_year":null,"regional":null,"definition":"Augmentative of 'bicha'; denotes an exaggeratedly effeminate gay man; used as an intensified slur from outsiders or as exaggerated camp self-identification within the community.","english_term":"total queen / raging queen","english_translation_quality":"approximate","notes":"The augmentative suffix -ona amplifies the effeminacy implication and intensifies both the insult potential and the camp self-affirmation potential. Common in both hostile and celebratory contexts depending on speaker identity."}
{"term":"bixona","lang":"pt-BR","script":"latin","romanization":null,"category":"identities_orientations","subcategory":null,"concept":"effeminate_gay_man","is_novel_concept":false,"register":"slang_crude","crude":80,"technical":0,"recognition_pct_current":82,"recognition_pct_peak":82,"peak_year":null,"regional":null,"definition":"Alternate orthography of 'bichona' using 'x' for 'ch'; same meaning and register; especially common in informal digital and social media writing.","english_term":"total queen / raging queen","english_translation_quality":"approximate","notes":"The 'x' spelling reflects a widespread Brazilian internet orthographic convention where 'x' represents the /ʃ/ phoneme of 'ch'; functionally identical to 'bichona' semantically; recognition slightly lower than bichona among older generations unfamiliar with digital spelling conventions."}
{"term":"sapatão","lang":"pt-BR","script":"latin","romanization":null,"category":"identities_orientations","subcategory":null,"concept":"lesbian_slur","is_novel_concept":false,"register":"slang_crude","crude":70,"technical":0,"recognition_pct_current":99,"recognition_pct_peak":99,"peak_year":null,"regional":null,"definition":"The most common Brazilian Portuguese slur and partially-reclaimed identity term for a lesbian, especially a masculine-presenting one; literally the augmentative of 'sapato' (shoe), evoking the stereotype of lesbians wearing large or men's footwear.","english_term":"dyke","english_translation_quality":"approximate","notes":"Widely reclaimed within Brazilian lesbian communities as a proud political and cultural marker; the shoe etymology encodes older stereotypes about masculine gender presentation. Severity is strongly context-dependent: celebratory within the community, offensive from hostile outsiders. The augmentative -ão also implies bigness/strength, which the community has embraced."}
{"term":"sapatilha","lang":"pt-BR","script":"latin","romanization":null,"category":"identities_orientations","subcategory":null,"concept":"lesbian_slur","is_novel_concept":false,"register":"slang_neutral","crude":32,"technical":0,"recognition_pct_current":60,"recognition_pct_peak":60,"peak_year":null,"regional":null,"definition":"Diminutive of 'sapata'/'sapatão'; a softer or affectionate term for a lesbian, literally 'ballet slipper' or 'little shoe'; sometimes implies a more femme or recently out lesbian relative to the more butch connotations of sapatão.","english_term":"baby dyke / soft dyke","english_translation_quality":"approximate","notes":"The diminutive suffix -ilha substantially softens the slur into something approaching gentle teasing or affectionate in-group use; far less widely known than sapatão; sometimes used to contrast a more feminine or younger lesbian against the more butch/older sapatão image."}
{"term":"sapata","lang":"pt-BR","script":"latin","romanization":null,"category":"identities_orientations","subcategory":null,"concept":"lesbian_slur","is_novel_concept":false,"register":"slang_crude","crude":62,"technical":0,"recognition_pct_current":80,"recognition_pct_peak":80,"peak_year":null,"regional":null,"definition":"Slur for a lesbian in Brazilian Portuguese, especially a masculine-presenting one; the base form of the shoe-family lexical set from which 'sapatão' (augmentative) and 'sapatilha' (diminutive) derive.","english_term":"dyke","english_translation_quality":"approximate","notes":"Less frequent in contemporary speech than sapatão; the plain form without augmentative suffix carries less intensity. The shoe etymology — sapato (shoe) → sapata → sapatão — is the most productive lesbian-slur word family in Brazilian Portuguese."}
{"term":"boiola","lang":"pt-BR","script":"latin","romanization":null,"category":"identities_orientations","subcategory":null,"concept":"effeminate_man_slur","is_novel_concept":false,"register":"slang_crude","crude":83,"technical":0,"recognition_pct_current":97,"recognition_pct_peak":97,"peak_year":null,"regional":null,"definition":"A highly offensive Brazilian slur for an effeminate or gay man, explicitly conflating homosexuality with cowardice and lack of masculine resolve; etymology is disputed, possibly from 'boi' (ox) or a phonetic variant of 'bicha'.","english_term":"faggot / sissy","english_translation_quality":"approximate","notes":"Carries a stronger implication of cowardice and weakness than 'viado' or 'bicha'; frequently used as a general masculinity attack even against men whose sexual orientation is not in question; common across generations and social classes; less reclaimed by gay communities than 'bicha'."}
{"term":"paneleiro","lang":"pt-BR","script":"latin","romanization":null,"category":"identities_orientations","subcategory":null,"concept":"gay_man_slur","is_novel_concept":false,"register":"slang_crude","crude":77,"technical":0,"recognition_pct_current":82,"recognition_pct_peak":82,"peak_year":null,"regional":null,"definition":"A slur for a gay man derived from 'panela' (cooking pot/pan), invoking stereotypes of domestic femininity; used equivalently to 'bicha' or 'viado'.","english_term":"faggot","english_translation_quality":"approximate","notes":"The kitchen-utensil etymology encodes the stereotype of gay men performing 'women's work'; also widely used in European Portuguese (Portugal), where it may be even more prevalent than in Brazil; less universally known in Brazil than viado/bicha but still very broadly recognized."}
